package space

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// vectors mirrors testdata/vectors.json, generated by running the reference
// implementation (@atproto/space 0.0.0-spaces-alpha-20261022141228) with fixed keys. See
// testdata/SOURCE.
type vectors struct {
	Now    int64 `json:"now"`
	LtHash []struct {
		Ops    [][2]string `json:"ops"`
		State  string      `json:"state"`
		Digest string      `json:"digest"`
		Empty  bool        `json:"empty"`
	} `json:"lthash"`
	Commits []struct {
		Ctx     CommitCtx `json:"ctx"`
		Records []struct {
			Collection string `json:"collection"`
			Rkey       string `json:"rkey"`
			Cid        string `json:"cid"`
		} `json:"records"`
		Data         string `json:"data"`
		SharedSecret string `json:"sharedSecret"`
		Mac          string `json:"mac"`
		MacHeader    string `json:"macHeader"`
	} `json:"commits"`
	RecordMacs []struct {
		URI          string `json:"uri"`
		Cid          string `json:"cid"`
		SharedSecret string `json:"sharedSecret"`
		Mac          string `json:"mac"`
		MacHeader    string `json:"macHeader"`
	} `json:"recordMacs"`
	Kem []struct {
		KemPrivateKey       string `json:"kemPrivateKey"`
		KemKey              string `json:"kemKey"`
		KeyShare            string `json:"keyShare"`
		SharedSecret        string `json:"sharedSecret"`
		WantMacHeader       string `json:"wantMacHeader"`
		WantRecordMacHeader string `json:"wantRecordMacHeader"`
	} `json:"kem"`
	HTTPSig []struct {
		KeyDid  string            `json:"keyDid"`
		Headers map[string]string `json:"headers"`
	} `json:"httpsig"`
	Tokens []struct {
		Type       string          `json:"type"`
		JWT        string          `json:"jwt"`
		SigningKey string          `json:"signingKey"`
		Opts       json.RawMessage `json:"opts"`
	} `json:"tokens"`
}

func loadVectors(t *testing.T) vectors {
	t.Helper()
	b, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
